const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Punjab and Haryana region (approximate boundaries)
  const punjab = ee.Geometry.Polygon([
    [[73.5, 29.5], [76.8, 29.5], [76.8, 32.5], [73.5, 32.5], [73.5, 29.5]]
  ]);

  const haryana = ee.Geometry.Polygon([
    [[74.5, 27.5], [77.5, 27.5], [77.5, 30.5], [74.5, 30.5], [74.5, 27.5]]
  ]);

  const region = punjab.union(haryana);

  // Time period
  const startDate = '2024-11-01';
  const endDate = '2024-11-30';

  // Load VIIRS fire data
  const fires = ee.FeatureCollection('FIRMS')
    .filter(ee.Filter.date(startDate, endDate))
    .filterBounds(region);

  const fireCount = fires.size().getInfo();

  console.log(`Date Range: ${startDate} to ${endDate}`);
  console.log(`Region: Punjab and Haryana, India`);
  console.log(`Total VIIRS Fire Detections: ${fireCount}`);
  console.log(`Threshold: 20,000 fires`);

  if (fireCount === 0) {
    console.log('No fire data found for the period.');
    console.log('<answer>C1</answer>');
    return;
  }

  if (fireCount < 20000) {
    console.log('Fire count is LESS than 20,000');
    console.log('<answer>A</answer>');
  } else {
    console.log('Fire count is 20,000 or MORE');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
